/**
 * Runtime resolution and the limitations each runtime imposes on the authored surface.
 */
import { join } from "node:path";
import { displayPath, pushConfigDiagnostic } from "./context.js";
/**
 * Validate the authored runtime. An unrecognized value is an error
 * diagnostic and falls back to local — a typo must not silently pick a
 * different harness for every turn.
 */
export function resolveRuntime(ctx, agentDir, runtime) {
    if (runtime === undefined || runtime === "local" || runtime === "cloud") {
        return runtime ?? "local";
    }
    pushConfigDiagnostic(ctx, {
        severity: "error",
        path: displayPath(ctx, join(agentDir, "agent.ts")),
        message: `runtime must be "local" or "cloud"; got ${JSON.stringify(runtime)}.`,
    });
    return "local";
}
export function warnCloudRuntimeLimitations(ctx, agentDir, counts) {
    const agentPath = displayPath(ctx, join(agentDir, "agent.ts"));
    if (!counts.hasCloudOptions) {
        pushConfigDiagnostic(ctx, {
            severity: "warning",
            path: agentPath,
            message: 'runtime: "cloud" usually needs a `cloud` block (e.g. repos / env). Without it the Cursor cloud API may reject create.',
        });
    }
    if (counts.agentTools > 0) {
        pushConfigDiagnostic(ctx, {
            severity: "warning",
            path: displayPath(ctx, join(agentDir, "tools")),
            message: 'Agent tools (execution: "agent") are described on the first cloud prompt (with script bodies); they are not written into the cloud VM filesystem automatically.',
        });
    }
    if (counts.skills > 0) {
        pushConfigDiagnostic(ctx, {
            severity: "warning",
            path: displayPath(ctx, join(agentDir, "skills")),
            message: "Authored skills reach cloud agents through native store discovery: hosted deployments write the deployment store's skills/ directory; local serve/run with a personal API key writes agent-serve/<agent>/skills/ on the USER store. Without a reachable store, only skills already in the cloud repo are visible.",
        });
    }
    if (counts.seedFiles > 0) {
        pushConfigDiagnostic(ctx, {
            severity: "warning",
            path: displayPath(ctx, join(agentDir, "sandbox")),
            message: "sandbox/workspace seed files reach cloud agents through the Agent Store, not the checkout: hosted deployments write the deployment store's workspace/ directory; local serve/run with a personal API key writes agent-serve/<agent>/workspace/ on the USER store. The first cloud prompt names the mounted directory. Without a reachable store, cloud turns do not see them.",
        });
    }
}
